const raw = (($json.body||$json).phone) || (($json.body||$json).caller_phone) || '';
let d = String(raw).replace(/[^0-9]/g,'');
let phone = '';
if (d.length===10) phone='+1'+d;
else if (d.length===11 && d[0]==='1') phone='+'+d;
else if (d.length>0) phone='+'+d;

const b=$json.body||$json;
return [{ json: { phone, redisKey: phone?'patient:'+phone:'', incoming: b } }];

const b=$('Normalize Phone').item.json.incoming||{};
const phone=$('Normalize Phone').item.json.phone;
if(!phone){return [{json:{skipWrite:true}}];}
let prof={}; try{const r=$json.existingRaw; if(r&&typeof r==='string')prof=JSON.parse(r); else if(r&&typeof r==='object'&&r)prof=r;}catch(e){prof={};}
const set=(k,v)=>{ if(v!==undefined&&v!==null&&String(v).trim()!=='') prof[k]=String(v).trim(); };
set('first_name',b.first_name); set('last_name',b.last_name);
prof.caller_phone=phone;
set('dob',b.dob); set('insurance_plan',b.insurance_plan); set('preferred_pharmacy',b.preferred_pharmacy);
set('known_medications',b.known_medications); set('clinic_location',b.clinic_location);
if(b.last_call_reason)prof.last_call_reason=String(b.last_call_reason);
if(b.last_call_summary)prof.last_call_summary=String(b.last_call_summary);
prof.is_existing_patient='true';
prof.last_call_date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
prof.updated_at=new Date().toISOString();
const callEntry=JSON.stringify({date:prof.last_call_date,reason:prof.last_call_reason||'',summary:prof.last_call_summary||'',source:b.source||'GHL',clinic:prof.clinic_location||''});
return [{json:{skipWrite:false,redisKey:'patient:'+phone,redisCallsKey:'patient:'+phone+':calls',profileJson:JSON.stringify(prof),callEntry,saved:prof}}];

